def fix_paths(s):
    s = s.replace('src="assets/', 'src="../assets/')
    s = s.replace("src='assets/", "src='../assets/")
    s = s.replace('href="assets/', 'href="../assets/')
    s = s.replace("href='assets/", "href='../assets/")
    s = s.replace("url('assets/", "url('../assets/")
    s = s.replace('url("assets/', 'url("../assets/')
    for css in ['home-premium.css','international-hero.css','partners-ecosystem.css']:
        s = s.replace(f'href="{css}', f'href="../{css}')
    s = re.sub(r'(src=["\'])(?!https?://|data:|/|\.\./|assets/)([^/"\']+\.(?:png|jpe?g|webp|svg))', r'\1../\2', s, flags=re.I)
    return s


def lang_switch(filename, lang):
    if lang == 'en':
        return f'<span class="lang-switch" style="font-size:12px;white-space:nowrap;color:#74808d"><a href="../{filename}">RU</a>&nbsp;&nbsp;/&nbsp;&nbsp;<a href="{filename}" aria-current="page">EN</a>&nbsp;&nbsp;/&nbsp;&nbsp;<a href="../cz/{filename}">CZ</a></span>'
    return f'<span class="lang-switch" style="font-size:12px;white-space:nowrap;color:#74808d"><a href="../{filename}">RU</a>&nbsp;&nbsp;/&nbsp;&nbsp;<a href="../en/{filename}">EN</a>&nbsp;&nbsp;/&nbsp;&nbsp;<a href="{filename}" aria-current="page">CZ</a></span>'


def root_lang_switch(filename):
    return f'<span class="lang-switch" style="font-size:12px;white-space:nowrap;color:#74808d"><a href="{filename}" aria-current="page">RU</a>&nbsp;&nbsp;/&nbsp;&nbsp;<a href="en/{filename}">EN</a>&nbsp;&nbsp;/&nbsp;&nbsp;<a href="cz/{filename}">CZ</a></span>'


def install_switch(s, filename, switch):
    if 'class="lang-switch"' in s:
        s = re.sub(r'<span class="lang-switch"[^>]*>.*?</span>', switch, s, count=1, flags=re.S)
    elif '</nav>' in s:
        s = s.replace('</nav>', switch + '</nav>', 1)
    elif '</header>' in s:
        s = s.replace('</header>', switch + '</header>', 1)
    return s


def apply_map(s, mapping):
    for src in sorted(mapping, key=len, reverse=True):
        s = s.replace(src, mapping[src])
    return s


def localise_page(filename, lang, common, specific):
    src = ROOT / filename
    if not src.exists():
        print(f'Skip missing {src}')
        return
    s = src.read_text(encoding='utf-8')
    s = apply_map(s, common)
    s = apply_map(s, specific.get(filename, {}))
    s = re.sub(r'<html lang="[^"]+">', f'<html lang="{lang}">', s, count=1)
    s = fix_paths(s)
    s = install_switch(s, filename, lang_switch(filename, lang))
    if lang == 'en':
        s = s.replace('https://webridge.tech/ru/academy','https://webridge.tech/en/academy').replace('https://webridge.tech/ru','https://webridge.tech/en')
    elif lang == 'cz':
        s = s.replace('https://webridge.tech/ru/academy','https://webridge.tech/en/academy').replace('https://webridge.tech/ru','https://webridge.tech/en')
    out = ROOT / lang / filename
    out.parent.mkdir(parents=True, exist_ok=True)
    out.write_text(s, encoding='utf-8')
    residual = sorted(set(re.findall(r'[А-Яа-яЁё][^<>\n]{0,100}', s)))
    if residual:
        print(f'WARNING {lang}/{filename}: possible Cyrillic remains ({len(residual)})')


def patch_root_switches():
    for filename in PAGES:
        p = ROOT / filename
        if not p.exists():
            continue
        s = p.read_text(encoding='utf-8')
        s = install_switch(s, filename, root_lang_switch(filename))
        p.write_text(s, encoding='utf-8')


patch_root_switches()
for page in PAGES:
    localise_page(page, 'en', COMMON_EN, EN)
    localise_page(page, 'cz', COMMON_CZ, CZ)
print('Localised EN and CZ pages generated.')
